import axios from 'axios';

const client = axios.create({
  baseURL: 'http://localhost:3000/api',
});

// Мы упаковываем всё в один объект api и экспортируем его
export const api = {
  getProducts: async () => {
    const { data } = await client.get('/products');
    return data;
  },
  
  deleteProduct: async (id) => {
    await client.delete(`/products/${id}`);
  },
  
  createTestProduct: async () => {
    const { data } = await client.post('/products', {
      title: 'Новая тестовая видеокарта ' + Math.floor(Math.random() * 1000),
      category: 'GPU',
      price: 99999,
      description: 'Тестовое описание, чтобы пробить лимит в 20 символов и пройти валидацию.',
      stock: 5
    });
    return data;
  }
};
